head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[p > M > getEventTarget]<br/>이벤트가 실행된 컴포넌트의 기본 정보를 JSON 객체로 반환합니다.",
    "validation" : [
        "comp(필수) 파라미터로 이벤트 핸들러 내의 this 객체를 설정할 수 있어야 합니다.",
        "반환 객체의 pluginName 속성으로 컴포넌트의 플러그인 이름을 확인할 수 있어야 합니다.",
        "반환 객체의 id 속성으로 컴포넌트의 원래 ID 를 확인할 수 있어야 합니다.",
        "반환 객체의 realId 속성으로 렌더링 과정에서 할당된 실제 내부 ID 를 확인할 수 있어야 합니다.",
        "전달된 값이 undefined, null, 빈 문자열인 경우 빈 객체를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.target_input1_onchange = function () {
    var info = $p.getEventTarget(this);
    wf_body_bottom.getObj("scwin").setReturnValue("pluginName : " + info.pluginName + ", id : " + info.id + ", realId : " + info.realId);
}



scwin.target_btn1_onclick = function () {
    var info = $p.getEventTarget(this);
    wf_body_bottom.getObj("scwin").setReturnValue("pluginName : " + info.pluginName + ", id : " + info.id + ", realId : " + info.realId);
}



scwin.target_checkbox1_onchange = function () {
    var info = $p.getEventTarget(this);
    wf_body_bottom.getObj("scwin").setReturnValue("pluginName : " + info.pluginName + ", id : " + info.id + ", realId : " + info.realId);
}



scwin.btn_getEventTarget_empty_onclick = function () {
    var type = par_emptyType.getValue();
    var val;
    if (type === "null") {
        val = null;
    } else if (type === "undefined") {
        val = undefined;
    } else {
        val = "";
    }

    var info = $p.getEventTarget(val);
    var keys = Object.keys(info);
    wf_body_bottom.getObj("scwin").setReturnValue("getEventTarget(" + type + ") : 빈 객체 여부 → " + (keys.length === 0 ? "PASS" : "FAIL") + " (keys: " + keys.length + ")");
}
